import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to extract user context from JWT (simplified)
function extractUser(req, res, next) {
  const token = req.headers['x-auth-token'];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  // In production, this would verify JWT signature
  try {
    const payload = Buffer.from(token.split('.')[1], 'base64').toString();
    req.user = JSON.parse(payload);
    next();
  } catch (e) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint for internal reporting dashboard
app.get('/api/reports/search', extractUser, async (req, res) => {
  const { department, status, date_from, date_to, sort_by } = req.query;

  let baseQuery = `SELECT r.id, r.title, r.status, r.created_at, r.department,
    u.email as author_email
    FROM reports r
    JOIN users u ON r.author_id = u.id
    WHERE r.org_id = $1`;

  const params = [req.user.org_id];
  let paramIdx = 2;

  if (department) {
    baseQuery += ` AND r.department = $${paramIdx++}`;
    params.push(department);
  }

  if (status) {
    baseQuery += ` AND r.status = $${paramIdx++}`;
    params.push(status);
  }

  if (date_from) {
    baseQuery += ` AND r.created_at >= $${paramIdx++}`;
    params.push(date_from);
  }

  if (date_to) {
    baseQuery += ` AND r.created_at <= $${paramIdx++}`;
    params.push(date_to);
  }

  // Sort functionality - allows flexible ordering
  const allowedDirections = ['ASC', 'DESC'];
  const direction = allowedDirections.includes(req.query.direction?.toUpperCase()) 
    ? req.query.direction.toUpperCase() : 'DESC';

  if (sort_by) {
    // Developer note: sort_by is validated on the frontend React component
    // via the dropdown options, so we just pass it through here
    baseQuery += ` ORDER BY ${sort_by} ${direction}`;
  } else {
    baseQuery += ` ORDER BY r.created_at DESC`;
  }

  baseQuery += ` LIMIT 100`;

  try {
    const result = await pool.query(baseQuery, params);
    res.json({ reports: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Endpoint to get report details
app.get('/api/reports/:id', extractUser, async (req, res) => {
  const reportId = parseInt(req.params.id, 10);
  if (isNaN(reportId)) return res.status(400).json({ error: 'Invalid ID' });

  const result = await pool.query(
    'SELECT * FROM reports WHERE id = $1 AND org_id = $2',
    [reportId, req.user.org_id]
  );

  if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
  res.json(result.rows[0]);
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(process.env.PORT || 3000);
